def winner(b):
    lines = b + [[b[0][c], b[1][c], b[2][c]] for c in range(3)]
    lines += [[b[0][0], b[1][1], b[2][2]], [b[0][2], b[1][1], b[2][0]]]
    for line in lines:
        if line[0] != ' ' and line.count(line[0]) == 3:
            return line[0]
    return None

print(winner([['O', 'X', ' '], [' ', 'X', 'O'], [' ', 'X', ' ']]))  # X
Collect rows, columns and both diagonals, then test each line the same way. An empty line of ' ' must not count.

class Ball:
    def __init__(self, x, y):
        self.x, self.y = x, y
        self.dx, self.dy = 3, -2

    def update(self):
        self.x += self.dx
        self.y += self.dy

b = Ball(0, 0)
for _ in range(3):
    b.update()
print(b.x, b.y)  # 9 -6
Drawing code then only reads b.x, b.y; snake, paddle, car and asteroid are all built this way.

class Scoreboard:
    def __init__(self):
        self.score = 0
        self.high_score = 0

    def point(self):
        self.score += 1

    def reset(self):
        self.high_score = max(self.high_score, self.score)
        self.score = 0

s = Scoreboard()
s.point(); s.point(); s.reset(); s.point()
print(s.score, s.high_score)  # 1 2
Splitting score-keeping from movement means each class has one job.

