class Vec:
    def __init__(self, x, y):
        self.x, self.y = x, y
    def __add__(self, o):
        return Vec(self.x + o.x, self.y + o.y)
    def __mul__(self, k):
        return Vec(self.x * k, self.y * k)

pos = Vec(0, 0) + Vec(200, 100) * 0.5
print(pos.x, pos.y)  # 100.0 50.0
pygame.Vector2 works the same: position += velocity * dt.

