def grey(p):
    v = (p[0] + p[1] + p[2]) // 3
    return (v, v, v)

print(grey((200, 100, 30)))  # (110, 110, 110)
Equal channels make grey; weighted averages (0.299r + 0.587g + 0.114b) look more natural.

def clamp(v):
    return min(255, max(0, v))

def brighten(p, amount):
    r, g, b = p
    return (clamp(r + amount), clamp(g + amount), clamp(b + amount))

print(brighten((250, 100, 3), 10))   # (255, 110, 13)
print(brighten((250, 100, 3), -10))  # (240, 90, 0)
Values outside 0-255 are invalid colours (Pillow raises or wraps them).

